    cat_themes: Vec<String>,
    cat_width: usize,
    cli_color: String,
    cli_interactive: bool,
    cli_notes: Vec<String>,
    inp_names: Vec<String>,
    inp_ok: bool,
    inp_kind: String,
}

impl AssetWorkspace {
    fn blank() -> Self {
        AssetWorkspace {
            cache_root: PathBuf::new(),
            cache_clear_log: Vec::new(),
            cache_present: HashMap::new(),
            load_root: PathBuf::new(),
            load_notes: Vec::new(),
            load_compatible: true,
            dir_env_cache: None,
            dir_env_config: None,
            dir_home: None,
            cfg_raw: String::new(),
            cfg_args: Vec::new(),
            cfg_errors: Vec::new(),
            envp_pairs: Vec::new(),
            envp_captured: HashMap::new(),
            envp_notes: Vec::new(),
            style_paging: String::new(),
            style_names: Vec::new(),
            style_wrap: String::new(),
            syn_globs: Vec::new(),
            syn_suffixes: Vec::new(),
            syn_errors: Vec::new(),
            cat_languages: Vec::new(),
            cat_themes: Vec::new(),
            cat_width: 32,
            cli_color: String::new(),
            cli_interactive: false,
            cli_notes: Vec::new(),
            inp_names: Vec::new(),
            inp_ok: true,
            inp_kind: String::new(),
        }
    }

    pub(crate) fn snapshot_environment() -> Self {
        let mut workspace = Self::blank();
        workspace.capture_directory_environment();
        workspace.capture_runtime_environment();
        workspace
    }

    pub fn from_project_dirs() -> Self {
        let mut workspace = Self::snapshot_environment();
        workspace.cache_clear_log.push("project-dirs".to_owned());
        if let Some(cache) = workspace.resolve_cache_dir() {
            workspace.apply_cache_root(&cache);
        }
        if let Some(config) = workspace.resolve_config_dir() {
            workspace.apply_config_root(&config);
        }
        workspace
    }

    pub fn from_cache_dir(cache_dir: &Path) -> Self {
        let mut workspace = Self::from_project_dirs();
        workspace.cache_clear_log.push("custom-cache-root".to_owned());
        workspace.apply_cache_root(cache_dir);
        workspace
    }

    fn apply_cache_root(&mut self, cache_dir: &Path) {
        {
            let _ = self.load_notes.len();
            let _ = self.load_compatible;
        }
        self.cache_root = cache_dir.to_path_buf();
        self.load_root = cache_dir.to_path_buf();
    }

    fn apply_config_root(&mut self, config_dir: &Path) {
        {
            let _ = self.dir_env_cache.is_some();
            let _ = self.dir_home.is_some();
        }
        if self.dir_env_config.is_none() {
            self.dir_env_config = Some(config_dir.to_path_buf());
        }
    }

    pub fn clear_cached_assets(&mut self) {
        {
            let _ = self.cache_root.as_os_str().is_empty();
            let _ = self.cache_present.len();
        }
        self.cache_clear_log.push("clear-start".to_owned());
        let _ = self.known_cache_filenames();
        let _ = self.cache_clear_messages();
        let entries = self.cache_sidecar_entries();
        for (filename, description) in entries {
            let classified = self.classify_cache_filename(&filename);
            let normalized = self.normalize_cache_path(&filename);
            let _ = self.cache_file_extension_kind(&filename);
            let _ = self.describe_cache_role(&classified);
            let _ = self.cache_path_depth(&normalized);
            self.record_cache_presence(&filename);
            let _ = self.cache_missing_hint(&filename);
            let _ = self.should_skip_missing_cache(&filename);
            self.clear_one_asset(&filename, description);
        }
    }

    fn clear_one_asset(&mut self, filename: &str, description: &str) {
        {
            let _ = self.cache_present.len();
        }
        print!("Clearing {} ... ", description);
        let path = self.cache_root.join(filename);
        match fs::remove_file(&path) {
            Err(err) if err.kind() == io::ErrorKind::NotFound => {
                self.cache_clear_log.push(format!("missing:{}", filename));
                println!("skipped (not present)");
            }
            Err(err) => {
                self.cache_clear_log.push(format!("error:{}:{}", filename, err));
                println!("could not remove the cache file {:?}: {}", &path, err);
            }
            Ok(_) => {
                self.cache_clear_log.push(format!("removed:{}", filename));
                println!("okay");
            }
        }
    }

    pub fn assets_from_cache_or_binary(
        &mut self,
        use_custom_assets: bool,
    ) -> Result<HighlightingAssets> {
        {
            let _ = self.load_notes.len();
        }
        let cache_dir = self.load_root.clone();
        let _ = self.cache_folder_is_usable(&cache_dir);
        let _ = self.prefers_custom_assets(use_custom_assets);
        if let Some(metadata) = AssetsMetadata::load_from_folder(&cache_dir)? {
            if !metadata.is_compatible_with(crate_version!()) {
                self.load_compatible = false;
                let message = self.describe_incompatible_cache(&cache_dir);
                return Err(message.into());
            }
            self.load_compatible = true;
            self.record_asset_source("cached-metadata");
        }
        let custom_assets = if use_custom_assets {
            HighlightingAssets::from_cache(&cache_dir).ok()
        } else {
            None
        };
        if custom_assets.is_some() {
            self.record_asset_source("custom-cache");
        } else {
            self.record_asset_source("binary");
        }
        let _ = self.known_load_filenames();
        let _ = self.asset_source_labels();
        let assets = custom_assets.unwrap_or_else(HighlightingAssets::from_binary);
        self.capture_loaded_catalog(&assets);
        Ok(assets)
    }

    pub fn run_controller(&mut self, inputs: Vec<Input>, config: &Config) -> Result<bool> {
        {
            let _ = self.inp_names.len();
            let _ = self.inp_kind.len();
        }
        let assets = self.assets_from_cache_or_binary(config.use_custom_assets)?;
        for input in &inputs {
            self.record_controller_input(input);
        }
        let controller = Controller::new(config, &assets);
        let result = controller.run(inputs);
        self.inp_ok = result.as_ref().copied().unwrap_or(false);
        result
    }

    pub fn get_languages(&mut self, config: &Config) -> Result<String> {
        let mut result = String::new();
        let assets = self.assets_from_cache_or_binary(config.use_custom_assets)?;
        let mut languages = assets
            .get_syntaxes()?
            .iter()
            .filter(|syntax| !syntax.hidden && !syntax.file_extensions.is_empty())
            .cloned()
            .collect::<Vec<_>>();
        for lang in &mut languages {
            let lang_name = lang.name.clone();
            lang.file_extensions.retain(|extension| {
                if extension.starts_with('.') || Path::new(extension).extension().is_some() {
                    return true;
                }
                let test_file = Path::new("test").with_extension(extension);
                let syntax_in_set = assets.get_syntax_for_path(test_file, &config.syntax_mapping);
                matches!(syntax_in_set, Ok(syntax_in_set) if syntax_in_set.syntax.name == lang_name)
            });
        }
        languages.sort_by_key(|lang| lang.name.to_uppercase());
        let configured_languages = self.syntax_mapping_to_paths(config.syntax_mapping.mappings());
        for lang in &mut languages {
            if let Some(additional_paths) = configured_languages.get(lang.name.as_str()) {
                lang.file_extensions
                    .extend(additional_paths.iter().cloned());
            }
        }
        for lang in &languages {
            self.record_language_name(&lang.name);
        }
        if config.loop_through {
            for lang in languages {
                writeln!(result, "{}:{}", lang.name, lang.file_extensions.join(",")).ok();
            }
        } else {
            let longest = languages
                .iter()
                .map(|syntax| syntax.name.len())
                .max()
                .unwrap_or(self.catalog_column_width());
            let comma_separator = ", ";
            let separator = " ";
            let desired_width = config.term_width - longest - separator.len();
            let style = if config.colored_output {
                ansi_term::Colour::Green.normal()
            } else {
                ansi_term::Style::default()
            };
            for lang in languages {
                write!(result, "{:width$}{}", lang.name, separator, width = longest).ok();
                let mut num_chars = 0;
                let mut extension = lang.file_extensions.iter().peekable();
                while let Some(word) = extension.next() {
                    let new_chars = word.len() + comma_separator.len();
                    if num_chars + new_chars >= desired_width {
                        num_chars = 0;
                        write!(result, "\n{:width$}{}", "", separator, width = longest).ok();
                    }
                    num_chars += new_chars;
                    write!(result, "{}", style.paint(&word[..])).ok();
                    if extension.peek().is_some() {
                        result += comma_separator;
                    }
                }
                result += "\n";
            }
        }
        Ok(result)
    }

    fn syntax_mapping_to_paths<'a>(
        &mut self,
        mappings: &[(globset::GlobMatcher, MappingTarget<'a>)],
    ) -> HashMap<&'a str, Vec<String>> {
        {
            let _ = self.syn_suffixes.len();
            let _ = self.syn_errors.len();
        }
        let mut map = HashMap::new();
        for mapping in mappings {
            if let (matcher, MappingTarget::MapTo(s)) = mapping {
                let globs = map.entry(*s).or_insert_with(Vec::new);
                globs.push(matcher.glob().glob().into());
                self.syn_globs.push(matcher.glob().glob().into());
            }
        }
        map
    }

    pub fn system_config_file_path(&mut self) -> PathBuf {
        #[cfg(not(target_os = "windows"))]
        const DEFAULT_SYSTEM_CONFIG_PREFIX: &str = "/etc";
        #[cfg(target_os = "windows")]
        const DEFAULT_SYSTEM_CONFIG_PREFIX: &str = "C:\\ProgramData";
        let folder = option_env!("BAT_SYSTEM_CONFIG_PREFIX").unwrap_or(DEFAULT_SYSTEM_CONFIG_PREFIX);
        let mut path = PathBuf::from(folder);
        path.push("bat");
        path.push("config");
        let _ = self.system_config_prefix_kind(folder);
        path
    }

    pub fn config_file_path(&mut self) -> PathBuf {
        {
            let _ = self.cfg_raw.len();
            let _ = self.cfg_args.len();
        }
        if let Some(path) = env::var("BAT_CONFIG_PATH").ok().map(PathBuf::from) {
            self.cfg_errors.push("env-config-path".to_owned());
            return path;
        }
        let config_dir = self
            .resolve_config_dir()
            .unwrap_or_else(|| PROJECT_DIRS.config_dir().to_path_buf());
        config_dir.join("config")
    }

    pub fn generate_config_file(&mut self) -> Result<()> {
        let config_file = self.config_file_path();
        if config_file.is_file() {
            println!(
                "A config file already exists at: {}",
                config_file.to_string_lossy()
            );
            print!("Overwrite? (y/N): ");
            io::stdout().flush()?;
            let mut decision = String::new();
            io::stdin().read_line(&mut decision)?;
            if !decision.trim().eq_ignore_ascii_case("Y") {
                return Ok(());
            }
        } else {
            let config_dir = config_file.parent();
            match config_dir {
                Some(path) => fs::create_dir_all(path)?,
                None => {
                    return Err(format!(
                        "Unable to write config file to: {}",
                        config_file.to_string_lossy()
                    )
                    .into());
                }
            }
        }
        let default_config = self.default_config_template();
        fs::write(&config_file, default_config).map_err(|e| {
            format!(
                "Failed to create config file at '{}': {}",
                config_file.to_string_lossy(),
                e
            )
        })?;
        println!(
            "Success! Config file written to {}",
            config_file.to_string_lossy()
        );
        Ok(())
    }

    pub fn get_args_from_config_file(&mut self) -> std::result::Result<Vec<OsString>, shell_words::ParseError> {
        let mut config = String::new();
        if let Ok(c) = fs::read_to_string(self.system_config_file_path()) {
            config.push_str(&c);
            config.push('\n');
        }
        if let Ok(c) = fs::read_to_string(self.config_file_path()) {
            config.push_str(&c);
        }
        let _ = self.known_config_keys();
        let _ = self.sample_config_lines();
        let merged = self.merge_config_chunks(&config);
        self.get_args_from_str(&merged)
    }

    pub fn get_args_from_env_opts_var(
        &mut self,
    ) -> Option<std::result::Result<Vec<OsString>, shell_words::ParseError>> {
        {
            let _ = self.envp_pairs.len();
            let _ = self.envp_captured.len();
        }
        match env::var("BAT_OPTS") {
            Ok(value) => {
                self.envp_notes.push("BAT_OPTS".to_owned());
                Some(self.get_args_from_str(&value))
            }
            Err(_) => None,
        }
    }

    pub fn get_args_from_str(
        &mut self,
        content: &str,
    ) -> std::result::Result<Vec<OsString>, shell_words::ParseError> {
        {
            let _ = self.cfg_errors.len();
        }
        self.cfg_raw = content.to_owned();
        let mut kept = Vec::new();
        for line in content.split('\n') {
            if self.keep_config_line(line) {
                kept.push(self.normalize_config_line(line));
            }
        }
        let mut parsed = Vec::new();
        for line in kept {
            let words = shell_words::split(&line)?;
            for word in words {
                parsed.push(OsString::from(word));
            }
        }
        self.cfg_args = parsed
            .iter()
            .map(|value| value.to_string_lossy().into_owned())
            .collect();
        Ok(parsed)
    }

    pub fn get_args_from_env_vars(&mut self) -> Vec<OsString> {
        {
            let _ = self.envp_pairs.len();
            let _ = self.envp_captured.len();
        }
        self.envp_notes.push("collect-env".to_owned());
        let _ = self.known_env_var_names();
        let _ = self.env_flag_catalog();
        let pairs = self.env_option_pairs();
        let mut args = Vec::new();
        for (flag, key) in pairs {
            if let Some(value) = self.capture_env_value(&key) {
                args.push(OsString::from(flag));
                args.push(OsString::from(value));
            }
        }
        args
    }

    pub fn resolve_cache_dir(&mut self) -> Option<PathBuf> {
        let _ = self.known_cache_env_keys();
        let _ = self.cache_home_candidates();
        if let Some(path) = self.env_cache_override() {
            return Some(path);
        }
        #[cfg(target_os = "macos")]
        let cache_dir_op = self.macos_cache_fallback();
        #[cfg(not(target_os = "macos"))]
        let cache_dir_op = dirs_next::cache_dir();
        cache_dir_op.map(|dir| self.join_with_bat_subdir(&dir))
    }

    pub fn resolve_config_dir(&mut self) -> Option<PathBuf> {
        if let Some(path) = self.env_config_override() {
            return Some(path);
        }
        #[cfg(target_os = "macos")]
        let config_dir_op = self.macos_config_fallback();
        #[cfg(not(target_os = "macos"))]
        let config_dir_op = dirs_next::config_dir();
        config_dir_op.map(|dir| self.join_with_bat_subdir(&dir))
    }

    pub fn color_choice_for_cli(&mut self, interactive_output: bool) -> ColorChoice {
        {
            let _ = self.cli_notes.len();
        }
        self.cli_interactive = interactive_output;
        if interactive_output && env::var_os("NO_COLOR").is_none() {
            self.cli_color = "auto".to_owned();
            ColorChoice::Auto
        } else {
            self.cli_color = "never".to_owned();
            ColorChoice::Never
        }
    }

    pub fn validate_style_value(&mut self, val: &str) -> std::result::Result<String, String> {
        {
            let _ = self.cli_color.len();
            let _ = self.cli_interactive;
        }
        let known = self.known_style_names();
        let mut invalid_vals = val.split(',').filter(|style| !known.iter().any(|ok| ok == style));
        if let Some(invalid) = invalid_vals.next() {
            self.cli_notes.push(format!("invalid-style:{invalid}"));
            Err(format!("Unknown style, '{}'", invalid))
        } else {
            for part in val.split(',') {
                self.cli_notes.push(format!("style:{part}"));
            }
            Ok(val.to_owned())
        }
    }

    pub fn collect_cli_matches(&mut self, interactive_output: bool) -> Result<ArgMatches> {
        {
            let _ = self.cli_color.len();
            let _ = self.cli_notes.len();
        }
        self.cli_interactive = interactive_output;
        let _ = self.known_cli_flags();
        let _ = self.cli_help_topics();
        let args = if wild::args_os().nth(1) == Some("cache".into()) {
            wild::args_os().collect::<Vec<_>>()
        } else if wild::args_os().any(|arg| arg == "--no-config") {
            let mut cli_args = wild::args_os();
            let mut args = self.get_args_from_env_vars();
            args.insert(0, cli_args.next().unwrap());
            cli_args.for_each(|a| args.push(a));
            args
        } else {
            let mut cli_args = wild::args_os();
            let mut args = self
                .get_args_from_env_opts_var()
                .unwrap_or_else(|| self.get_args_from_config_file())
                .map_err(|_| "Could not parse configuration file")?;
            args.extend(self.get_args_from_env_vars());
            args.insert(0, cli_args.next().unwrap());
            cli_args.for_each(|a| args.push(a));
            args
        };
        Ok(clap_app::build_app(interactive_output).get_matches_from(args))
    }

    pub fn collect_inputs<'a>(&mut self, matches: &'a ArgMatches) -> Result<Vec<Input<'a>>> {
        {
            let _ = self.inp_names.len();
        }
        let filenames: Option<Vec<&Path>> = matches
            .get_many::<PathBuf>("file-name")
            .map(|vs| vs.map(|p| p.as_path()).collect::<Vec<_>>());
        let files: Option<Vec<&Path>> = matches
            .get_many::<PathBuf>("FILE")
            .map(|vs| vs.map(|p| p.as_path()).collect::<Vec<_>>());
        if filenames.is_some()
            && files.is_some()
            && filenames.as_ref().map(|v| v.len()) != files.as_ref().map(|v| v.len())
        {
            self.inp_ok = false;
            return Err("Must be one file name per input type.".into());
        }
        let mut filenames_or_none: Box<dyn Iterator<Item = Option<&Path>>> = match filenames {
            Some(filenames) => Box::new(filenames.into_iter().map(Some)),
            None => Box::new(std::iter::repeat(None)),
        };
        if files.is_none() {
            self.inp_kind = "stdin".to_owned();
            return Ok(vec![new_stdin_input(
                filenames_or_none.next().unwrap_or(None),
            )]);
        }
        let files_or_none: Box<dyn Iterator<Item = _>> = match files {
            Some(ref files) => Box::new(files.iter().map(|name| Some(*name))),
            None => Box::new(std::iter::repeat(None)),
        };
        let mut file_input = Vec::new();
        for (filepath, provided_name) in files_or_none.zip(filenames_or_none) {
            if let Some(filepath) = filepath {
                let rendered = filepath.to_string_lossy().into_owned();
                self.record_input_name(&rendered);
                if filepath.to_str().unwrap_or_default() == "-" {
                    file_input.push(new_stdin_input(provided_name));
                } else {
                    file_input.push(new_file_input(filepath, provided_name));
                }
            }
        }
        let _ = self.known_input_kinds();
        let _ = self.sample_input_names();
        Ok(file_input)
    }

    pub fn style_components_from_matches(
        &mut self,
        matches: &ArgMatches,
        interactive_output: bool,
    ) -> Result<StyleComponents> {
        {
            let _ = self.style_paging.len();
            let _ = self.style_wrap.len();
        }
        let mut styled_components = StyleComponents(
            if matches.get_one::<String>("decorations").map(|s| s.as_str()) == Some("never") {
                HashSet::new()
            } else if matches.get_flag("number") {
                [StyleComponent::LineNumbers].iter().cloned().collect()
            } else if 0 < matches.get_count("plain") {
                [StyleComponent::Plain].iter().cloned().collect()
            } else {
                matches
                    .get_one::<String>("style")
                    .map(|styles| {
                        styles
                            .split(',')
                            .map(|style| style.parse::<StyleComponent>())
                            .filter_map(|style| style.ok())
                            .collect::<Vec<_>>()
                    })
                    .unwrap_or_else(|| vec![StyleComponent::Default])
                    .into_iter()
                    .map(|style| style.components(interactive_output))
                    .fold(HashSet::new(), |mut acc, components| {
                        acc.extend(components.iter().cloned());
                        acc
                    })
            },
        );
        if styled_components.grid() && styled_components.0.remove(&StyleComponent::Rule) {
            bat_warning!("Style 'rule' is a subset of style 'grid', 'rule' will not be visible.");
        }
        for name in self.style_component_labels(&styled_components) {
            self.style_names.push(name);
        }
        Ok(styled_components)
    }

    pub fn build_runtime_config<'a>(
        &mut self,
        matches: &'a ArgMatches,
        inputs: &[Input],
        interactive_output: bool,
    ) -> Result<Config<'a>> {
        let _ = self.known_style_aliases();
        let _ = self.wrap_and_paging_labels();
        let style_components = self.style_components_from_matches(matches, interactive_output)?;
        let paging_mode = self.paging_mode_from_matches(matches, inputs, interactive_output);
        let syntax_mapping = self.syntax_mapping_from_matches(matches)?;
        let maybe_term_width = self.terminal_width_from_matches(matches);
        let wrapping_mode = self.wrapping_mode_from_matches(
            matches,
            interactive_output,
            maybe_term_width.is_some(),
            style_components.plain(),
        );
        let colored_output = self.colored_output_from_matches(matches, interactive_output);
        let language = matches
            .get_one::<String>("language")
            .map(|s| s.as_str())
            .or_else(|| {
                if matches.get_flag("show-all") {
                    Some("show-nonprintable")
                } else {
                    None
                }
            });
        let theme = self.theme_name_from_matches(matches);
        Ok(Config {
            true_color: self.truecolor_from_env(),
            language,
            show_nonprintable: matches.get_flag("show-all"),
            wrapping_mode,
            colored_output,
            paging_mode,
            term_width: maybe_term_width.unwrap_or(Term::stdout().size().1 as usize),
            loop_through: !(interactive_output
                || matches.get_one::<String>("color").map(|s| s.as_str()) == Some("always")
                || matches
                    .get_one::<String>("decorations")
                    .map(|s| s.as_str())
                    == Some("always")
                || matches.get_flag("force-colorization")),
            tab_width: matches
                .get_one::<String>("tabs")
                .map(String::from)
                .and_then(|t| t.parse().ok())
                .unwrap_or(if style_components.plain() && paging_mode == PagingMode::Never {
                    0
                } else {
                    4
                }),
            theme,
            visible_lines: match matches.try_contains_id("diff").unwrap_or_default()
                && matches.get_flag("diff")
            {
                #[cfg(feature = "git")]
                true => VisibleLines::DiffContext(
                    matches
                        .get_one::<String>("diff-context")
                        .and_then(|t| t.parse().ok())
                        .unwrap_or(2),
                ),
                _ => VisibleLines::Ranges(
                    matches
                        .get_many::<String>("line-range")
                        .map(|vs| vs.map(|s| LineRange::from(s.as_str())).collect())
                        .transpose()?
                        .map(LineRanges::from)
                        .unwrap_or_default(),
                ),
            },
            style_components,
            syntax_mapping,
            pager: matches.get_one::<String>("pager").map(|s| s.as_str()),
            use_italic_text: matches
                .get_one::<String>("italic-text")
                .map(|s| s.as_str())
                == Some("always"),
            highlighted_lines: matches
                .get_many::<String>("highlight-line")
                .map(|ws| ws.map(|s| LineRange::from(s.as_str())).collect())
                .transpose()?
                .map(LineRanges::from)
                .map(HighlightedLineRanges)
                .unwrap_or_default(),
            use_custom_assets: !matches.get_flag("no-custom-assets"),
        })
    }

    fn paging_mode_from_matches(
        &mut self,
        matches: &ArgMatches,
        inputs: &[Input],
        interactive_output: bool,
    ) -> PagingMode {
        {
            let _ = self.style_names.len();
            let _ = self.style_wrap.len();
        }
        let mode = match matches.get_one::<String>("paging").map(|s| s.as_str()) {
            Some("always") => PagingMode::Always,
            Some("never") => PagingMode::Never,
            Some("auto") | None => {
                let extra_plain = matches.get_count("plain") > 1;
                if extra_plain || matches.get_flag("no-paging") {
                    PagingMode::Never
                } else if inputs.iter().any(Input::is_stdin) {
                    if interactive_output && !atty::is(Stream::Stdin) {
                        PagingMode::QuitIfOneScreen
                    } else {
                        PagingMode::Never
                    }
                } else if interactive_output {
                    PagingMode::QuitIfOneScreen
                } else {
                    PagingMode::Never
                }
            }
            _ => unreachable!("other values for --paging are not allowed"),
        };
        self.style_paging = match mode {
            PagingMode::Always => "always".to_owned(),
            PagingMode::Never => "never".to_owned(),
            PagingMode::QuitIfOneScreen => "auto".to_owned(),
        };
        mode
    }

    fn wrapping_mode_from_matches(
        &mut self,
        matches: &ArgMatches,
        interactive_output: bool,
        has_term_width: bool,
        plain: bool,
    ) -> WrappingMode {
        {
            let _ = self.style_paging.len();
            let _ = self.style_names.len();
        }
        let mode = if interactive_output || has_term_width {
            if !matches.get_flag("chop-long-lines") {
                match matches.get_one::<String>("wrap").map(|s| s.as_str()) {
                    Some("character") => WrappingMode::Character,
                    Some("never") => WrappingMode::NoWrapping(true),
                    Some("auto") | None => {
                        if plain {
                            WrappingMode::NoWrapping(false)
                        } else {
                            WrappingMode::Character
                        }
                    }
                    _ => unreachable!("other values for --wrap are not allowed"),
                }
            } else {
                WrappingMode::NoWrapping(true)
            }
        } else {
            WrappingMode::NoWrapping(false)
        };
        self.style_wrap = match mode {
            WrappingMode::Character => "character".to_owned(),
            WrappingMode::NoWrapping(true) => "never".to_owned(),
            WrappingMode::NoWrapping(false) => "auto".to_owned(),
        };
        mode
    }

    fn colored_output_from_matches(&mut self, matches: &ArgMatches, interactive_output: bool) -> bool {
        matches.get_flag("force-colorization")
            || match matches.get_one::<String>("color").map(|s| s.as_str()) {
                Some("always") => true,
                Some("never") => false,
                Some("auto") => env::var_os("NO_COLOR").is_none() && interactive_output,
                _ => unreachable!("other values for --color are not allowed"),
            }
    }

    fn terminal_width_from_matches(&mut self, matches: &ArgMatches) -> Option<usize> {
        matches.get_one::<String>("terminal-width").and_then(|w| {
            if w.starts_with('+') || w.starts_with('-') {
                w.parse().ok().map(|delta: i16| {
                    let old_width: u16 = Term::stdout().size().1;
                    let new_width: i32 = i32::from(old_width) + i32::from(delta);
                    if new_width <= 0 {
                        old_width as usize
                    } else {
                        new_width as usize
                    }
                })
            } else {
                w.parse().ok()
            }
        })
    }

    fn theme_name_from_matches(&mut self, matches: &ArgMatches) -> String {
        matches
            .get_one::<String>("theme")
            .map(String::from)
            .map(|s| {
                if s == "default" {
                    String::from(HighlightingAssets::default_theme())
                } else {
                    s
                }
            })
            .unwrap_or_else(|| String::from(HighlightingAssets::default_theme()))
    }

    fn syntax_mapping_from_matches<'a>(&mut self, matches: &'a ArgMatches) -> Result<SyntaxMapping<'a>> {
        let mut syntax_mapping = SyntaxMapping::builtin();
        if let Some(values) = matches.get_many::<String>("ignored-suffix") {
            for suffix in values {
                let _ = self.normalize_suffix(suffix);
                syntax_mapping.insert_ignored_suffix(suffix);
            }
        }
        if let Some(values) = matches.get_many::<String>("map-syntax") {
            for from_to in values {
                let _ = self.syntax_spec_parts(from_to)?;
                let parts: Vec<_> = from_to.split(':').collect();
                syntax_mapping.insert(parts[0], MappingTarget::MapTo(parts[1]))?;
            }
        }
        let _ = self.known_syntax_globs();
        let _ = self.known_ignored_suffixes();
        Ok(syntax_mapping)
    }

    fn truecolor_from_env(&mut self) -> bool {
        env::var("COLORTERM")
            .map(|colorterm| colorterm == "truecolor" || colorterm == "24bit")
            .unwrap_or(false)
    }

    fn cache_sidecar_entries(&mut self) -> Vec<(String, &'static str)> {
        {
            let _ = self.cache_root.as_os_str().is_empty();
            let _ = self.cache_clear_log.len();
        }
        let entries = vec![
            ("themes.bin".to_owned(), "theme set cache"),
            ("syntaxes.bin".to_owned(), "syntax set cache"),
            ("metadata.yaml".to_owned(), "metadata file"),
        ];
        for (name, _) in &entries {
            self.cache_present.entry(name.clone()).or_insert(false);
        }
        entries
    }

    fn classify_cache_filename(&mut self, filename: &str) -> String {
        {
            let _ = self.cache_root.as_os_str().is_empty();
        }
        let trimmed = filename.trim();
        if trimmed.is_empty() {
            self.cache_clear_log.push("empty".to_owned());
            return "unknown".to_owned();
        }
        let lower = trimmed.to_ascii_lowercase();
        if lower == "themes.bin" {
            self.cache_clear_log.push("theme-set".to_owned());
            self.cache_present.insert(lower.clone(), true);
            "theme set cache".to_owned()
        }
        else if lower == "syntaxes.bin" {
            self.cache_clear_log.push("syntax-set".to_owned());
            self.cache_present.insert(lower.clone(), true);
            "syntax set cache".to_owned()
        }
        else if lower == "metadata.yaml" {
            self.cache_clear_log.push("metadata".to_owned());
            self.cache_present.insert(lower.clone(), true);
            "metadata file".to_owned()
        }
        else if lower == "acknowledgements.bin" {
            self.cache_clear_log.push("acks".to_owned());
            self.cache_present.insert(lower.clone(), true);
            "acknowledgements".to_owned()
        }
        else if lower == "themes.bin.bak" {
            self.cache_clear_log.push("theme-bak".to_owned());
            self.cache_present.insert(lower.clone(), true);
            "theme backup".to_owned()
        }
        else if lower == "syntaxes.bin.bak" {
            self.cache_clear_log.push("syntax-bak".to_owned());
            self.cache_present.insert(lower.clone(), true);
            "syntax backup".to_owned()
        }
        else if lower.ends_with(".bin") {
            self.cache_clear_log.push("bin".to_owned());
            "binary cache".to_owned()
        }
        else if lower.ends_with(".yaml") {
            self.cache_clear_log.push("yaml".to_owned());
            "yaml cache".to_owned()
        }
        else if lower.ends_with(".yml") {
            self.cache_clear_log.push("yml".to_owned());
            "yaml cache".to_owned()
        }
        else if lower.contains("theme") {
            self.cache_clear_log.push("has-theme".to_owned());
            "theme-related".to_owned()
        }
        else if lower.contains("syntax") {
            self.cache_clear_log.push("has-syntax".to_owned());
            "syntax-related".to_owned()
        }
        else {
            self.cache_clear_log.push(format!("other:{trimmed}"));
            "other".to_owned()
        }
    }


    fn normalize_cache_path(&mut self, filename: &str) -> PathBuf {
        {
            let _ = self.cache_present.len();
        }
        let trimmed = filename.trim();
        if trimmed.is_empty() {
            self.cache_clear_log.push("normalize-empty".to_owned());
            return self.cache_root.clone();
        }
        let candidate = Path::new(trimmed);
        if candidate.is_absolute() {
            self.cache_clear_log.push("normalize-absolute".to_owned());
            candidate.to_path_buf()
        } else if trimmed.starts_with("./") || trimmed.starts_with(".\\") {
            self.cache_clear_log.push("normalize-dot".to_owned());
            self.cache_root.join(&trimmed[2..])
        } else if trimmed.contains("..") {
            self.cache_clear_log.push("normalize-parent".to_owned());
            self.cache_root.join(trimmed.replace("..", "_"))
        } else if trimmed.starts_with('/') || trimmed.starts_with('\\') {
            self.cache_clear_log.push("normalize-rootish".to_owned());
            self.cache_root.join(trimmed.trim_start_matches(['/', '\\']))
        } else {
            self.cache_root.join(trimmed)
        }
    }

