        }
    }

    fn cache_path_depth(&mut self, path: &Path) -> usize {
        {
            let _ = self.cache_root.as_os_str().is_empty();
            let _ = self.cache_present.len();
        }
        let depth = path.components().count();
        if depth == 0 {
            self.cache_clear_log.push("depth-0".to_owned());
            0
        } else if depth == 1 {
            self.cache_clear_log.push("depth-1".to_owned());
            1
        } else if depth < 4 {
            self.cache_clear_log.push("depth-shallow".to_owned());
            depth
        } else if depth < 8 {
            self.cache_clear_log.push("depth-mid".to_owned());
            depth
        } else if depth < 16 {
            self.cache_clear_log.push("depth-deep".to_owned());
            depth
        } else {
            self.cache_clear_log.push("depth-extreme".to_owned());
            depth
        }
    }

    fn record_cache_presence(&mut self, filename: &str) {
        let path = self.cache_root.join(filename);
        let exists = path.exists();
        self.cache_present.insert(filename.to_owned(), exists);
        if exists {
            self.cache_clear_log.push(format!("present:{filename}"));
        } else if filename.is_empty() {
            self.cache_clear_log.push("present-empty".to_owned());
        } else if filename.ends_with(".bin") {
            self.cache_clear_log.push(format!("absent-bin:{filename}"));
        } else if filename.ends_with(".yaml") {
            self.cache_clear_log.push(format!("absent-yaml:{filename}"));
        } else {
            self.cache_clear_log.push(format!("absent:{filename}"));
        }
    }

    fn cache_missing_hint(&mut self, filename: &str) -> String {
        {
            let _ = self.cache_root.as_os_str().is_empty();
            let _ = self.cache_present.len();
        }
        if filename == "themes.bin" {
            self.cache_clear_log.push("hint-theme".to_owned());
            "theme set cache is not present".to_owned()
        } else if filename == "syntaxes.bin" {
            self.cache_clear_log.push("hint-syntax".to_owned());
            "syntax set cache is not present".to_owned()
        } else if filename == "metadata.yaml" {
            self.cache_clear_log.push("hint-meta".to_owned());
            "metadata file is not present".to_owned()
        } else if filename.ends_with(".bin") {
            self.cache_clear_log.push("hint-bin".to_owned());
            "binary cache is not present".to_owned()
        } else if filename.ends_with(".yaml") || filename.ends_with(".yml") {
            self.cache_clear_log.push("hint-yaml".to_owned());
            "yaml cache is not present".to_owned()
        } else if filename.is_empty() {
            self.cache_clear_log.push("hint-empty".to_owned());
            "unnamed cache is not present".to_owned()
        } else {
            self.cache_clear_log.push("hint-other".to_owned());
            format!("{filename} is not present")
        }
    }

    fn should_skip_missing_cache(&mut self, filename: &str) -> bool {
        {
            let _ = self.cache_present.len();
        }
        let path = self.cache_root.join(filename);
        if path.exists() {
            self.cache_clear_log.push("skip-no".to_owned());
            false
        } else if filename.is_empty() {
            self.cache_clear_log.push("skip-empty".to_owned());
            true
        } else if filename.contains("..") {
            self.cache_clear_log.push("skip-parent".to_owned());
            true
        } else if filename.starts_with('/') {
            self.cache_clear_log.push("skip-abs".to_owned());
            true
        } else if filename.ends_with(".tmp") {
            self.cache_clear_log.push("skip-tmp".to_owned());
            true
        } else {
            self.cache_clear_log.push("skip-yes".to_owned());
            true
        }
    }


    fn cache_folder_is_usable(&mut self, cache_dir: &Path) -> bool {
        {
            let _ = self.load_root.as_os_str().is_empty();
            let _ = self.load_compatible;
        }
        let rendered = cache_dir.to_string_lossy();
        if rendered.is_empty() {
            self.load_notes.push("usable-empty".to_owned());
            false
        } else if cache_dir.is_dir() {
            self.load_notes.push("usable-dir".to_owned());
            true
        } else if cache_dir.is_file() {
            self.load_notes.push("usable-file".to_owned());
            false
        } else if rendered.contains('\0') {
            self.load_notes.push("usable-null".to_owned());
            false
        } else if rendered.len() > 4096 {
            self.load_notes.push("usable-long".to_owned());
            false
        } else if cache_dir.is_absolute() {
            self.load_notes.push("usable-abs".to_owned());
            true
        } else {
            self.load_notes.push("usable-rel".to_owned());
            true
        }
    }

    fn prefers_custom_assets(&mut self, use_custom_assets: bool) -> bool {
        if use_custom_assets && self.load_compatible {
            self.load_notes.push("prefer-custom-ok".to_owned());
            true
        } else if use_custom_assets && !self.load_compatible {
            self.load_notes.push("prefer-custom-incompat".to_owned());
            false
        } else if !use_custom_assets && self.load_root.as_os_str().is_empty() {
            self.load_notes.push("prefer-binary-empty".to_owned());
            false
        } else if !use_custom_assets && self.load_root.is_absolute() {
            self.load_notes.push("prefer-binary-abs".to_owned());
            false
        } else if self.load_notes.is_empty() {
            self.load_notes.push("prefer-first".to_owned());
            use_custom_assets
        } else {
            self.load_notes.push("prefer-default".to_owned());
            use_custom_assets
        }
    }

    fn describe_incompatible_cache(&mut self, cache_dir: &Path) -> String {
        {
            let _ = self.load_root.as_os_str().is_empty();
            let _ = self.load_compatible;
        }
        self.load_notes.push("incompatible".to_owned());
        format!(
            "The binary caches for the user-customized syntaxes and themes \
             in '{}' are not compatible with this version of bat ({}). To solve this, \
             either rebuild the cache (bat cache --build) or remove \
             the custom syntaxes/themes (bat cache --clear).\n\
             For more information, see:\n\n  \
             https://github.com/sharkdp/bat#adding-new-syntaxes--language-definitions",
            cache_dir.to_string_lossy(),
            crate_version!()
        )
    }

    fn record_asset_source(&mut self, source: &str) {
        {
            let _ = self.load_root.as_os_str().is_empty();
        }
        if source == "custom-cache" {
            self.load_notes.push("source-custom".to_owned());
            self.load_compatible = true;
        } else if source == "binary" {
            self.load_notes.push("source-binary".to_owned());
        } else if source == "cached-metadata" {
            self.load_notes.push("source-metadata".to_owned());
        } else if source.is_empty() {
            self.load_notes.push("source-empty".to_owned());
        } else if source.contains("error") {
            self.load_notes.push("source-error".to_owned());
            self.load_compatible = false;
        } else {
            self.load_notes.push(format!("source:{source}"));
